comments:
/* ===== 兜底评述模块（模板未提供 comments 时使用） ===== */
.be-comments {
  background: #ffffff;
  border-top: 1px solid #ececec;
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Microsoft YaHei", "Segoe UI", sans-serif;
}
.be-comment {
  display: flex;
  gap: 10px;
  padding: 10px 16px;
  border-bottom: 1px solid #f5f5f5;
}
.be-comment:last-child { border-bottom: none; }
.be-comment-avatar {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background-size: cover;
  background-position: center;
  background-color: #eee;
  flex-shrink: 0;
}
.be-comment-main { flex: 1; min-width: 0; }
.be-comment-meta { display: flex; align-items: baseline; flex-wrap: wrap; gap: 3px 6px; }
.be-comment-name { font-size: 12.5px; color: #333; font-weight: 700; }
.be-comment-id { font-size: 11px; color: #999; }
.be-comment-time { font-size: 11px; color: #bbb; }
.be-comment-text { font-size: 13px; color: #444; line-height: 1.6; margin-top: 2px; white-space: pre-wrap; overflow-wrap: break-word; }
.be-comment[data-kind="user"] .be-comment-name { color: #c13584; }
